import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;

public class Main {

    public static void main(String[] args) throws Exception {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;

        BufferedReader br = new BufferedReader(new InputStreamReader(inStream));
        PrintWriter pw = new PrintWriter(outStream);

        String line = br.readLine();
        String[] parts = line.split(" ");
        int n = Integer.parseInt(parts[0]);
        long k = Long.parseLong(parts[1]);

        Task task = new Task();
        task.execute(n, k, pw);
        pw.close();
    }
}

class Task {

    private static int mod = 998244353;

    public void execute(int n, long k, PrintWriter out) {
        long[] factorials = new long[200001];
        long[] inverses = new long[200001];
        factorials[0] = inverses[0] = 1;
        for (int i = 1; i < 200001; i++) {
            factorials[i] = factorials[i - 1] * i % mod;
            inverses[i] = inverses[i - 1] * powMod(i, mod - 2) % mod;
        }
        if (k >= n) {
            out.println(0);
            return;
        }
        if (k == 0) {
            out.println(factorials[n]);
            return;
        }
        int m = (int)(n - k);
        long total = 0;
        for (int i = 0; i <= m; i++) {
            long comb = getCombination(factorials, inverses, m, i);
            long term = powMod(m - i, n);
            if (i % 2 == 0) {
                total = (total + comb * term % mod) % mod;
            } else {
                total = (total - comb * term % mod + mod) % mod;
            }
        }
        long result = 2 * factorials[n] % mod * inverses[n - m] % mod * total % mod * inverses[m] % mod;
        out.println(result);
    }

    private long powMod(long base, long exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * cur % mod;
            cur = cur * cur % mod;
            exp >>= 1;
        }
        return res;
    }

    private long getCombination(long[] fac, long[] inv, int n, int m) {
        return fac[n] * inv[m] % mod * inv[n - m] % mod;
    }
}
